/* v3 — suppresses focus ring */
.btn { @apply focus:outline-none focus-visible:ring-2; }

/* v4 migration — MUST update outline-none to outline-hidden */
.btn { @apply focus:outline-hidden focus-visible:ring-2; }

/* If you don't update: outline: none literally means no outline
   AND no ring — your keyboard focus disappears entirely */
